class StickyHeader{constructor(i,t={}){if(!i)throw new Error("StickyHeader: 'id' is required.");if(this.header=document.getElementById(i),!this.header)throw new Error(`StickyHeader: Element with id '${i}' not found.`);this.options={offset:t.offset??150,threshold:t.threshold??4},this.lastY=window.scrollY,this.ticking=!1,this.bindEvents()}bindEvents(){window.addEventListener("scroll",()=>{this.ticking||(window.requestAnimationFrame(()=>this.update()),this.ticking=!0)})}update(){const i=window.scrollY;if(i<this.options.offset)return this.pin(),this.lastY=i,void(this.ticking=!1);i<this.lastY-this.options.threshold?this.pin():i>this.lastY+this.options.threshold&&this.unpin(),this.lastY=i,this.ticking=!1}pin(){this.header.classList.add("header--pinned"),this.header.classList.remove("header--unpinned")}unpin(){this.header.classList.add("header--unpinned"),this.header.classList.remove("header--pinned")}}